package com.eidolon.sc.mobile;

import android.content.*;import android.database.*;import android.database.sqlite.*;
import java.time.*;import java.util.*;import org.json.*;

/** One bounded document per role; writes participate in the same SQLite transaction as message delivery. */
final class LifeStore {
 static void create(SQLiteDatabase db){db.execSQL("ALTER TABLE messages ADD COLUMN generated_at INTEGER NOT NULL DEFAULT 0");db.execSQL("CREATE TABLE character_life(character TEXT PRIMARY KEY,revision INTEGER NOT NULL,body TEXT NOT NULL)");}
 static JSONObject read(ChatStore s,String who)throws Exception{try(Cursor c=s.getReadableDatabase().rawQuery("SELECT body FROM character_life WHERE character=?",new String[]{who})){return c.moveToFirst()?new JSONObject(c.getString(0)):null;}}
 static void put(ChatStore s,JSONObject row)throws Exception{LifeData.validate(row,Collections.singleton(row.getString("character")));ContentValues v=new ContentValues();v.put("character",row.getString("character"));v.put("revision",row.getLong("revision"));v.put("body",row.toString());s.getWritableDatabase().insertWithOnConflict("character_life",null,v,SQLiteDatabase.CONFLICT_REPLACE);}
 static JSONObject advance(Context c,ChatStore s,JSONObject personal,String who,Clock clock)throws Exception{
  SQLiteDatabase db=s.getWritableDatabase();db.beginTransaction();try{
   JSONObject old=read(s,who);if(old==null)old=LifeData.fresh(who,WritingEngine.character(WritingEngine.characters(c),who),clock);
   try(Cursor contact=db.rawQuery("SELECT coalesce(max(sent_at),0) FROM messages WHERE character=? AND role='user' AND sent_at<=?",new String[]{who,""+clock.millis()})){if(contact.moveToFirst())old.put("awakeUntil",contact.getLong(0)+ScheduleData.HALF_HOUR);}
   ZoneId zone=TemporalRuntime.zone(c,personal,who);LocalDate day=clock.instant().atZone(zone).toLocalDate();JSONObject today=ScheduleStore.entry(s,who,day.toString()),yesterday=ScheduleStore.entry(s,who,day.minusDays(1).toString());
   if(!c.getSharedPreferences("settings",0).getBoolean("hibiSchedules",false)){today=null;yesterday=null;}
   JSONObject next=LifeData.advance(old,clock,zone,today,yesterday,TemporalRuntime.override(c,who,clock.millis())!=null);
   if(!next.toString().equals(old.toString())){next.put("revision",old.getLong("revision")+(LifeData.semanticKey(next).equals(LifeData.semanticKey(old))?0:1));put(s,next);}else if(read(s,who)==null)put(s,next);
   db.setTransactionSuccessful();return next;
  }finally{db.endTransaction();}
 }
 static JSONObject snapshot(Context c,ChatStore s,JSONObject personal,String who,JSONObject temporal,String user,boolean proactive,Clock clock)throws Exception{
  JSONObject state=advance(c,s,personal,who,clock);JSONObject result=project(state,temporal,user,proactive,clock.millis(),TemporalRuntime.override(c,who,clock.millis()));result.put("allEvents",ReplyBasis.projectedEvents(state,user,clock.millis())).put("recentExpressions",state.optJSONArray("recentExpressions")==null?new JSONArray():state.getJSONArray("recentExpressions"));return result;
 }
 static JSONObject project(JSONObject state,JSONObject temporal,String user,boolean proactive,long now,JSONObject override)throws Exception{
  JSONObject out=new JSONObject().put("enabled",state.getBoolean("enabled")).put("revision",state.getLong("revision")).put("now",now);
  if(!state.getBoolean("enabled"))return out;
  JSONObject actual=state.optJSONObject("actual");if(actual!=null&&(now<actual.getLong("start")||now>=actual.getLong("end")))actual=null;long valid=now+30*60000L;if(actual!=null)valid=Math.min(valid,actual.getLong("end"));if(override!=null)valid=Math.min(valid,override.getLong("until"));
  JSONObject storedMood=state.getJSONObject("emotion"),mood=new JSONObject();for(String k:new String[]{"valence","energy","at","source","label"})mood.put(k,storedMood.get(k));String planned=temporal.optString("planned_state");double energy=mood.getDouble("energy");if(planned.equals("asleep"))energy=Math.min(energy,30);if(planned.equals("bedtime"))energy=Math.min(energy,45);mood.put("energy",energy);
  JSONObject projected=new JSONObject(state.toString()).put("emotion",mood);JSONObject cue=LifeData.cue(state,now);
  JSONArray references=LifeData.relevant(state,user,now),events=new JSONArray();for(int i=0;i<references.length();i++)events.put(projectEvent(references.getJSONObject(i)));if(cue!=null&&LifeData.find(events,cue.getString("id"))==null){if(events.length()==4)events.remove(3);events.put(projectEvent(cue));}
  out.put("validUntil",valid).put("clockRollback",state.optBoolean("clockRollback")).put("actual_simulated_activity",override!=null?override:actual==null?JSONObject.NULL:actual).put("emotion",mood).put("profile",projectProfile(state.getJSONObject("profile"))).put("goal",projectGoal(LifeData.goal(state))).put("events",events).put("proactive_cue",cue==null?JSONObject.NULL:projectEvent(cue)).put("behavior",BehaviorPlanner.plan(projected,temporal,user,proactive));
  ZoneId eventZone=ZoneId.of(state.optString("zone").isEmpty()?temporal.optString("timezone","UTC"):state.getString("zone"));for(int i=0;i<events.length();i++)dateEvent(events.getJSONObject(i),eventZone,now);if(out.optJSONObject("proactive_cue")!=null)dateEvent(out.getJSONObject("proactive_cue"),eventZone,now);
  JSONArray archived=LifeData.archivedRelevant(state,user,now);for(int i=0;i<archived.length();i++)dateEvent(archived.getJSONObject(i),eventZone,now);out.put("archived_history",archived);JSONArray selected=new JSONArray(),all=state.getJSONArray("memories");for(int i=all.length()-1;i>=0&&selected.length()<4;i--){JSONObject m=all.getJSONObject(i);if(m.optLong("at")<=now&&(m.optString("layer").equals("todo")||Recall.score(user,m.optString("text"))>0))selected.put(new JSONObject().put("eventId",m.getString("eventId")).put("layer",m.getString("layer")).put("status",m.getString("status")));}out.put("life_memories",selected);return out;
 }
 static void dateEvent(JSONObject e,ZoneId zone,long now)throws Exception{long at=e.optLong("at",e.optLong("start"));if(at<=0)at=e.optLong("start");if(at<=0)return;ZoneId effective=e.optString("zone").isEmpty()?zone:ZoneId.of(e.getString("zone"));ZonedDateTime date=Instant.ofEpochMilli(at).atZone(effective),current=Instant.ofEpochMilli(now).atZone(effective);e.put("localTime",date.toOffsetDateTime().toString()).put("daysBeforeCurrent",java.time.temporal.ChronoUnit.DAYS.between(date.toLocalDate(),current.toLocalDate()));}
 static JSONObject projectEvent(JSONObject event)throws Exception{JSONObject out=new JSONObject();for(String k:new String[]{"id","title","kind","status","at","start","end","zone","parent","source","goalId","resolvedBy","subject","eventVersion","topic"})if(event.has(k))out.put(k,event.get(k));return out;}
 static JSONObject projectProfile(JSONObject p)throws Exception{return new JSONObject().put("expressiveness",p.getInt("expressiveness")).put("confidence",p.getDouble("confidence")).put("interests",p.getJSONObject("interests")).put("coreSource","CharacterPrompts");}
 static Object projectGoal(JSONObject g)throws Exception{if(g==null)return JSONObject.NULL;JSONArray steps=new JSONArray();for(int i=0;i<g.getJSONArray("steps").length();i++){JSONObject s=g.getJSONArray("steps").getJSONObject(i);steps.put(new JSONObject().put("title",LifeData.shortText(s.getString("title"),100)).put("external",s.getBoolean("external")));}return new JSONObject().put("id",g.getString("id")).put("title",LifeData.shortText(g.getString("title"),100)).put("progress",g.getInt("progress")).put("status",g.getString("status")).put("steps",steps);}
 static boolean allowReach(ChatStore s,String who,JSONObject effects,long now)throws Exception{JSONObject state=read(s,who);if(state==null||!state.optBoolean("enabled"))return true;if(effects!=null&&ContinuityLife.supportsReach(state,effects.optJSONObject("continuity")))return true;String id=effects==null?"":effects.optString("cueId");if(id.isEmpty())return !state.optBoolean("eventOnlyReach");JSONObject e=LifeData.find(state.getJSONArray("events"),id);if(e==null||e.optLong("mentionedAt")>0||e.optLong("at")>now||!Arrays.asList("completed","open","awaiting_outcome").contains(e.optString("status")))return false;if(state.optBoolean("eventOnlyReach")){JSONArray mentions=effects.optJSONArray("mentions");if(mentions==null)return false;boolean found=false;for(int i=0;i<mentions.length();i++)if(id.equals(mentions.getJSONObject(i).optString("id")))found=true;if(!found)return false;}return true;}
 static JSONObject promptData(JSONObject snapshot){try{JSONObject data=new JSONObject(snapshot.toString());data.remove("allEvents");data.remove("replyBasis");return data;}catch(Exception e){return snapshot;}}
 static String prompt(JSONObject snapshot,boolean proactive){if(!snapshot.optBoolean("enabled"))return "";return "\n【角色虚拟生活参考；不是现实设备事件，也不是原作既定剧情】\n"+promptData(snapshot).toString()+"\n计划与实际模拟状态分开。只有source为virtual_simulation、simulation_rule或明确确认的生活记录才可当作虚拟经历，missed/planned/uncertain不能直接说成已确认发生；后文replyBasis.events若明确给inferred_completed，仅按普通日常推定继续交谈，保留不确定，不作确认或结算。archived_history是有限的过去目标摘要，按localTime、daysBeforeCurrent和status理解；已取消不等于已完成，归档不代表当前正在做，也不要补造摘要外的细节。生活事件时间戳用于今天/昨天；没有新经历就正常接话，不补造离线活动。情绪有惯性，不为了附和用户瞬间换心情，也不要每次报告状态。目标有前置阶段，external阶段须等待明确确认，不自行宣布比赛/考试结果。预计延迟跨活动边界时避免确定的‘此刻正在’措辞，采用能在等待后仍成立的表达。"+BehaviorPlanner.instruction()+ChatEnvelope.protocol(proactive);}
 static void delivered(Context c,ChatStore s,String who,JSONObject effect,String answer,long messageId,long now,JSONObject judgment)throws Exception{
  JSONObject state=read(s,who);if(state==null)return;boolean basisChanged=ReplyBasis.delivered(state,effect,answer,messageId,now);basisChanged=ExchangeIntent.delivered(state,effect,answer,messageId,now)||basisChanged;if(c.getSharedPreferences("settings",0).getBoolean("conversationContinuity",true))basisChanged=ContinuityLife.deliver(state,effect==null?null:effect.optJSONObject("continuity"),answer,messageId,now)||basisChanged;if(!state.optBoolean("enabled")){if(basisChanged){state.put("revision",state.getLong("revision")+1);put(s,state);}return;}
  JSONArray mentions=effect==null?null:effect.optJSONArray("mentions");if(mentions!=null)for(int i=0;i<mentions.length();i++){JSONObject m=mentions.getJSONObject(i),e=LifeData.find(state.getJSONArray("events"),m.optString("id"));if(e!=null&&!Arrays.asList("cancelled","missed","uncertain").contains(e.optString("status"))&&e.optString("title").equals(m.optString("title"))&&e.optLong("at")<=now&&answer.contains(m.optString("quote"))&&!m.optString("quote").isEmpty())e.put("mentionedAt",now).put("messageRef","message/"+messageId).put("mentionQuote",m.getString("quote"));}
  LifeData.decay(state,now);
  if(judgment!=null){double hurt=judgment.optDouble("hurt");if(hurt>0)LifeData.influence(state,"message/"+messageId,-Math.min(.25,hurt/30),now);}
  if(judgment!=null&&judgment.optDouble("warmth")>0)LifeData.influence(state,"warmth/"+(now/LifeData.HOUR),Math.min(.08,judgment.optDouble("warmth")/40),now);
  if(effect!=null&&effect.optJSONObject("behavior")!=null)state.put("lastBehavior",new JSONObject().put("goal",effect.getJSONObject("behavior").optString("goal")).put("at",now).put("messageRef","message/"+messageId));
  if(effect!=null&&effect.optLong("revision",-1)==state.optLong("revision")&&effect.optLong("validUntil",Long.MAX_VALUE)>=now&&effect.optJSONObject("new_goal")!=null){try{LifeData.seedGoal(state,effect.getJSONObject("new_goal"),now);JSONObject created=LifeData.goal(state);if(created!=null&&created.optLong("createdAt")==now&&created.optLong("sourceMessageId")==0)created.put("sourceMessageId",messageId).put("source","delivered_character_goal");}catch(Exception invalid){android.util.Log.w("EidolonLife","Ignored invalid goal proposal");}}
  state.put("revision",state.getLong("revision")+1);LifeData.prune(state,now);put(s,state);
 }
 static JSONObject edit(Context c,ChatStore s,JSONObject args)throws Exception{
  String who=args.getString("character");JSONObject personal=s.personal();JSONObject state;SQLiteDatabase db=s.getWritableDatabase();db.beginTransaction();try{
   state=read(s,who);if(state==null||args.getLong("revision")!=state.getLong("revision"))throw new Exception("生活状态已变化，请刷新后重试");String action=args.getString("operation");long now=System.currentTimeMillis();
   if(action.equals("settings")){state.put("enabled",args.getBoolean("enabled")).put("evolution",args.getBoolean("evolution")).put("eventOnlyReach",args.getBoolean("eventOnlyReach"));if(!state.getBoolean("enabled")){JSONArray events=state.getJSONArray("events");for(int i=0;i<events.length();i++){JSONObject e=events.getJSONObject(i);if(e.optString("status").equals("in_progress"))e.put("status","paused").put("source","simulation_disabled");}state.put("actual",JSONObject.NULL);}}
   else if(action.equals("addGoal")){for(int i=0;i<state.getJSONArray("goals").length();i++)if(ContinuityLife.open(state.getJSONArray("goals").getJSONObject(i)))throw new Exception("请先推进或取消当前目标");LifeData.seedGoal(state,args.getJSONObject("goal"),now);}
   else if(action.equals("pauseGoal")||action.equals("resumeGoal")){JSONObject g=LifeData.find(state.getJSONArray("goals"),args.getString("eventId"));if(!ContinuityLife.open(g)||action.equals("pauseGoal")&&!g.optString("status").equals("active")||action.equals("resumeGoal")&&!g.optString("status").equals("paused"))throw new Exception("目标状态已改变");String reason=LifeData.shortText(args.optString("reason",action.equals("pauseGoal")?"暂时搁置":"重新继续"),160);g.put("status",action.equals("pauseGoal")?"paused":"active");if(action.equals("pauseGoal"))g.put("pauseReason",reason);else g.remove("pauseReason");ContinuityLife.note(g,action,reason,g.getString("id"),0,now);JSONObject root=LifeData.find(state.getJSONArray("events"),g.getString("id"));if(root!=null)root.put("status",g.getString("status").equals("paused")?"paused":"open");}
   else if(action.equals("calibrate")){LifeData.calibrate(state,now,TemporalRuntime.zone(c,personal,who));for(int i=0;i<state.getJSONArray("goals").length();i++)ContinuityLife.note(state.getJSONArray("goals").getJSONObject(i),"calibrate","按已知记录校准时间", "",0,now);}
   else if(action.equals("resetTraits")){state.getJSONObject("profile").put("confidence",50.0).put("interests",new JSONObject()).put("lastEvolutionDay",LifeData.day(now,TemporalRuntime.zone(c,personal,who)));state.put("evolutionLog",new JSONArray()).put("profileBase",new JSONObject().put("at",now).put("confidence",50.0).put("interests",new JSONObject()));}
   else {JSONObject e=LifeData.find(state.getJSONArray("events"),args.getString("eventId"));if(e==null)throw new Exception("生活事件不存在");
    if(action.equals("confirm")){if(!e.getString("status").equals("awaiting_outcome")&&!(e.optString("kind").equals("issue")&&e.optString("status").equals("open")))throw new Exception("只有等待结果或未解决的事件可确认");if(!e.optString("kind").equals("issue"))LifeData.completeGoalStep(state,e,TemporalRuntime.zone(c,personal,who),now,true);e.put("status","completed").put("at",now).put("source","explicit_user_confirmation");LifeData.remember(state,e,"episodic",now);LifeData.remember(state,e,"todo",now);}
    else if(action.equals("correct")){e.put("previousTitle",e.getString("title")).put("title",LifeData.shortText(args.getString("title"),160)).put("source","explicit_user_correction").put("correctedAt",now);LifeData.remember(state,e,"episodic",now);}
    else if(action.equals("cancel")){e.put("status","cancelled").put("source","explicit_user_correction").put("at",now);LifeData.remember(state,e,"todo",now);JSONObject g=LifeData.find(state.getJSONArray("goals"),e.getString("id"));if(g!=null){g.put("status","cancelled").put("closedReason","用户在生活设置中取消");ContinuityLife.note(g,"cancel","用户在生活设置中取消",e.getString("id"),0,now);}if(e.optString("kind").equals("exchange"))e.put("exchangeStatus","withdrawn").put("version",ContinuityLife.version(e)+1);}
    else throw new Exception("未知生活操作");
   }
   if(!action.equals("settings")&&!action.equals("resetTraits")&&!action.equals("calibrate")&&!action.equals("addGoal")){JSONObject edited=LifeData.find(state.getJSONArray("events"),args.optString("eventId"));if(edited!=null)edited.put("eventVersion",edited.optLong("eventVersion",1)+1);}
   state.put("revision",state.getLong("revision")+1);put(s,state);db.setTransactionSuccessful();return state;
  }finally{db.endTransaction();}
 }
 static JSONObject decisionState(Context c,ChatStore s,String who,Clock clock)throws Exception{
  JSONObject state=read(s,who);return state==null?LifeData.fresh(who,WritingEngine.character(WritingEngine.characters(c),who),clock):state;
 }
 static boolean commitDecisions(Context c,ChatStore s,String who,String pending,long revision,JSONArray candidates,JSONArray decisions,long now)throws Exception{
  if(candidates==null||candidates.length()==0)return false;SQLiteDatabase db=s.getWritableDatabase();db.beginTransaction();try{
   ChatStore.PendingReply owner=s.pending(pending);if(owner==null||owner.revision!=revision||!owner.status.equals("generating"))return false;
   for(int i=0;i<candidates.length();i++){JSONObject candidate=candidates.getJSONObject(i);boolean found=false;for(ChatStore.Message m:MemoryNotebook.range(s,owner.session,candidate.getLong("sourceMessageId"),candidate.getLong("sourceMessageId")))if(m.role.equals("user")&&m.sentAt==candidate.getLong("sourceMentionedAt")&&m.zone.equals(candidate.getString("sourceTimeZone"))&&m.text.contains(candidate.getString("evidence")))found=true;if(!found)return false;}
   JSONObject state=decisionState(c,s,who,Clock.fixed(Instant.ofEpochMilli(now),ZoneOffset.UTC));boolean changed=EventContext.apply(state,candidates,decisions,now);
   if(changed){state.put("revision",state.getLong("revision")+1);LifeData.prune(state,now);put(s,state);}db.setTransactionSuccessful();return changed;
  }finally{db.endTransaction();}
 }
 static JSONObject basis(Context c,ChatStore s,JSONObject personal,String who,JSONObject temporal,List<ChatStore.Message> history,String user,boolean proactive,JSONArray retrieved,JSONObject answers,Clock clock)throws Exception{
  return ReplyBasis.build(temporal,snapshot(c,s,personal,who,temporal,user,proactive,clock),history,user,proactive,retrieved,answers);
 }
 static String conversationContext(Context c,ChatStore s,String who,long now,String date)throws Exception{
  JSONObject state=read(s,who);if(state==null)return "";ZoneId zone=TemporalRuntime.zone(c,s.personal(),who);long cutoff=Math.min(now,LocalDate.parse(date).plusDays(1).atStartOfDay(zone).toInstant().toEpochMilli()-1);JSONArray all=EventContext.views(state,cutoff,zone.getId()),selected=new JSONArray();for(int i=0;i<all.length();i++){JSONObject e=all.getJSONObject(i);if(e.optLong("mentionedAt")<=cutoff)selected.put(e);}return selected.length()==0?"":"\n【记录日期范围内的统一交谈事件；推定不得写成用户已确认或奖励已结算】\n"+selected;
 }
 static String conversationContext(Context c,ChatStore s,String who,long now)throws Exception{
  JSONObject state=read(s,who);if(state==null)return "";JSONArray view=EventContext.views(state,now,TemporalRuntime.zone(c,s.personal(),who).getId());return view.length()==0?"":"\n【同一事件交谈依据；推定不是用户确认，也不结算奖励】\n"+view;
 }
 static JSONObject planning(Context c,ChatStore s,JSONObject personal,String who,Clock clock)throws Exception{JSONObject state=advance(c,s,personal,who,clock);return state.optBoolean("enabled")?new JSONObject().put("goal",LifeData.goal(state)==null?JSONObject.NULL:LifeData.goal(state)).put("recentEvents",LifeData.relevant(state,"",clock.millis())).put("emotion",state.getJSONObject("emotion")).put("profile",state.getJSONObject("profile")).put("progressContext",ContinuityContext.project(state,personal,new JSONObject(),new JSONObject().put("timestamp",clock.millis()).put("timezone",state.optString("zone").isEmpty()?"UTC":state.getString("zone")),Collections.emptyList(),"",false,personal.optLong("memoryEpoch"),true)):new JSONObject();}
 static String diary(Context c,ChatStore s,String who,String date)throws Exception{JSONObject state=read(s,who);if(state==null||!state.optBoolean("enabled"))return "";ZoneId zone=TemporalRuntime.zone(c,s.personal(),who);JSONArray events=state.getJSONArray("events"),out=new JSONArray();for(int i=0;i<events.length()&&out.length()<6;i++){JSONObject e=events.getJSONObject(i);if(e.optLong("at")>0&&LifeData.day(e.getLong("at"),zone).equals(date)&&Arrays.asList("completed","open","awaiting_outcome").contains(e.optString("status")))out.put(e);}return out.length()==0?"":"\n当天已记录的虚拟生活事件（不是现实操作或原作剧情）："+out;}
 static JSONArray all(ChatStore s)throws Exception{JSONArray a=new JSONArray();try(Cursor c=s.getReadableDatabase().rawQuery("SELECT body FROM character_life ORDER BY character",null)){while(c.moveToNext())a.put(new JSONObject(c.getString(0)));}return a;}
 static void validateBackup(JSONObject data,Set<String> known)throws Exception{JSONArray a=data.getJSONArray("characterLife");if(a.length()>known.size())throw new Exception("生活备份角色过多");Set<String> seen=new HashSet<>();for(int i=0;i<a.length();i++){JSONObject row=a.getJSONObject(i);LifeData.validate(row,known);if(!seen.add(row.getString("character")))throw new Exception("生活备份角色重复");}}
 static String restoredRef(String ref,Map<String,Long> ids){if(!ref.startsWith("message/"))return ref;String id=ref.substring(8);Long mapped=ids.get(id);return mapped==null?"imported_missing/"+id:"message/"+mapped;}
 static void restore(ChatStore s,JSONObject backup,Map<String,Long> messages)throws Exception{
  s.getWritableDatabase().delete("character_life",null,null);if(backup.optInt("version")<14)return;
  Map<String,Long> ids=new HashMap<>();for(Map.Entry<String,Long> e:messages.entrySet())ids.put(e.getKey().substring(e.getKey().lastIndexOf('/')+1),e.getValue());
  JSONArray a=backup.getJSONArray("characterLife");for(int i=0;i<a.length();i++){
   JSONObject row=new JSONObject(a.getJSONObject(i).toString());JSONArray events=row.getJSONArray("events");for(int j=0;j<events.length();j++){JSONObject event=events.getJSONObject(j);event.put("messageRef",restoredRef(event.optString("messageRef"),ids));if(event.optString("kind").equals("conversation")){Long source=ids.get(""+event.optLong("sourceMessageId")),last=ids.get(""+event.optLong("lastSourceMessageId"));event.put("sourceMessageId",source==null?0:source).put("lastSourceMessageId",last==null?0:last).put("sourceMissing",source==null);if(event.has("lastAskedMessageId"))event.put("lastAskedMessageId",ids.getOrDefault(""+event.optLong("lastAskedMessageId"),0L));}}
   ContinuityStore.restore(row,ids);row.remove("eventChecks");row.remove("eventCheckFloor");JSONArray expressions=row.optJSONArray("recentExpressions");if(expressions!=null)for(int e=0;e<expressions.length();e++){JSONObject expression=expressions.getJSONObject(e);Long mapped=ids.get(""+expression.optLong("messageId"));expression.put("messageId",mapped==null?0:mapped);}
   JSONObject lastBehavior=row.optJSONObject("lastBehavior");if(lastBehavior!=null)lastBehavior.put("messageRef",restoredRef(lastBehavior.optString("messageRef"),ids));JSONArray archives=row.optJSONArray("archives");if(archives!=null)for(int j=0;j<archives.length();j++){JSONArray evidence=archives.getJSONObject(j).getJSONArray("evidence");for(int k=0;k<evidence.length();k++){JSONObject e=evidence.getJSONObject(k);e.put("messageRef",restoredRef(e.optString("messageRef"),ids));}}JSONObject emotion=row.getJSONObject("emotion");emotion.put("source",restoredRef(emotion.optString("source"),ids));JSONArray prior=row.getJSONArray("influences"),seen=new JSONArray();for(int j=0;j<prior.length();j++)seen.put(restoredRef(prior.getString(j),ids));row.put("influences",seen);put(s,row);
  }
 }
 private LifeStore(){}
}

